package com.bplus.share;
import android.app.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;
/** App-owned dialogs only. Android pickers/chooser/installer retain system UI. */
public final class AppDialog extends AlertDialog.Builder{
 public AppDialog(Context c){super(c,android.R.style.Theme_Material_Dialog_Alert);}
 @Override public AlertDialog create(){AlertDialog d=super.create();d.create();style(d);return d;}
 @Override public AlertDialog show(){AlertDialog d=create();d.show();return d;}
 static void style(AlertDialog d){Window w=d.getWindow();if(w==null)return;GradientDrawable bg=new GradientDrawable();bg.setColor(Ui.card);bg.setCornerRadius(Ui.dp(d.getContext(),22));bg.setStroke(Ui.dp(d.getContext(),1),Ui.border);w.setBackgroundDrawable(bg);w.setGravity(Gravity.CENTER);w.setWindowAnimations(R.style.AppDialogAnimation);w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_NOTHING);View decor=w.getDecorView();paint(decor);ListView list=d.getListView();if(list!=null)list.setOnScrollListener(new AbsListView.OnScrollListener(){public void onScrollStateChanged(AbsListView v,int state){paint(v);}public void onScroll(AbsListView v,int first,int visible,int total){paint(v);}});for(int which:new int[]{AlertDialog.BUTTON_POSITIVE,AlertDialog.BUTTON_NEGATIVE,AlertDialog.BUTTON_NEUTRAL}){Button b=d.getButton(which);if(b!=null){b.setTextColor((b.getText().toString().equals(d.getContext().getString(R.string.action_delete))||b.getText().toString().equals(d.getContext().getString(R.string.remove_device_chat)))?0xffff6565:Ui.accent);b.setAllCaps(false);b.setTypeface(App.cairoSB);}}int width=Math.min(d.getContext().getResources().getDisplayMetrics().widthPixels-Ui.dp(d.getContext(),36),Ui.dp(d.getContext(),430));w.setLayout(width,-2);}
 static void paint(View v){if(v instanceof TextView){TextView t=(TextView)v;t.setTextColor(Ui.text);t.setTypeface(App.cairo);if(v instanceof EditText){t.setHintTextColor(Ui.dim);t.setBackground(Ui.round(Ui.field,10,v.getContext()));}}if(v instanceof CompoundButton)((CompoundButton)v).setButtonTintList(android.content.res.ColorStateList.valueOf(Ui.accent));if(v instanceof CheckedTextView)((CheckedTextView)v).setCheckMarkTintList(android.content.res.ColorStateList.valueOf(Ui.accent));if(v instanceof ViewGroup){ViewGroup group=(ViewGroup)v;for(int i=0;i<group.getChildCount();i++)paint(group.getChildAt(i));}}
}
